/**
 * Resolves the request's `Actor` for a given org slug, or throws
 * `unauthorized` / `forbidden`. Every Server Action starts here.
 *
 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
 * this module is the seam between "there is an HTTP request with a cookie"
 * and the rest of the app, which knows nothing about requests.
 */
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { findOrgById } from "@/server/repositories/organization-repository";
import { resolveActorForOrg } from "@/server/services/session-service";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
export class UnauthorizedError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedError";
  }
}

/** Thrown when the session is valid but has no membership in the target org. */
export class NoMembershipError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly orgSlug: string) {
    super(`You are not a member of "${orgSlug}".`);
    this.name = "NoMembershipError";
  }
}

/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
export async function getActor(orgSlug: string): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();

  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) throw new NoMembershipError(orgSlug);

  return actor;
}

/** Non-throwing variant, for layouts that render a signed-out state. */
export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
  try {
    return await getActor(orgSlug);
  } catch (error) {
    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
      return null;
    }
    throw error;
  }
}

/**
 * The `Actor` for an org already identified by id — used by Route Handlers
 * that receive an `orgId` in the payload rather than a slug in the path. The
 * session's active org must match, which `assertOrgScope()` enforces.
 *
 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
 * with a single repository lookup rather than by widening that signature —
 * the slug is the only handle the session layer knows.
 */
export async function requireActorFor(orgId: OrgId): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();
  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);

  const org = await findOrgById(orgId);
  if (org === null) throw new NoMembershipError(orgId);

  const actor = await resolveActorForOrg(principal, org.slug);
  if (actor === null) throw new NoMembershipError(org.slug);

  assertOrgScope(actor, orgId);
  return actor;
}
/**
 * Timestamp helpers: ISO round-tripping, relative formatting, due-date and
 * digest-window arithmetic.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 */
import type { IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
 * issue cards and comment headers all use.
 */
export function formatRelative(
  value: IsoTimestamp,
  reference: Date = new Date(),
): string {
  const deltaMs = parseIso(value).getTime() - reference.getTime();
  const past = deltaMs < 0;
  const abs = Math.abs(deltaMs);

  const phrase = ((): string => {
    if (abs < MINUTE_MS) return "just now";
    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
  })();

  if (phrase === "just now") return phrase;
  return past ? `${phrase} ago` : `in ${phrase}`;
}

/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

/** True when a due date exists and has already passed. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
): boolean {
  if (dueAt === null) return false;
  return parseIso(dueAt).getTime() < reference.getTime();
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The 24-hour window a digest covers, ending at today's `digestHourUtc`. If
 * that hour has not arrived yet on `reference`'s day, the window is the one
 * that ended yesterday — so a job run early never mails an empty digest and
 * then skips the real one.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  const end = new Date(
    Date.UTC(
      reference.getUTCFullYear(),
      reference.getUTCMonth(),
      reference.getUTCDate(),
      digestHourUtc,
      0,
      0,
      0,
    ),
  );
  if (end.getTime() > reference.getTime()) {
    end.setUTCDate(end.getUTCDate() - 1);
  }

  return {
    start: toIsoTimestamp(new Date(end.getTime() - DAY_MS)),
    end: toIsoTimestamp(end),
  };
}
/**
 * ULID generation and validation. Every branded id in the app is produced
 * here, so ids sort lexicographically by creation time and the repositories
 * can use them as pagination cursors without a separate sort column.
 */
/** Crockford base32, minus I, L, O and U. */
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const TIME_LENGTH = 10;
const RANDOM_LENGTH = 16;

const ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;

function encodeTime(time: number): string {
  let remaining = time;
  let out = "";
  for (let i = 0; i < TIME_LENGTH; i += 1) {
    const mod = remaining % 32;
    out = ALPHABET[mod] + out;
    remaining = (remaining - mod) / 32;
  }
  return out;
}

function encodeRandom(next: () => number): string {
  let out = "";
  for (let i = 0; i < RANDOM_LENGTH; i += 1) {
    out += ALPHABET[next() % 32];
  }
  return out;
}

/** A fresh, monotonically-sortable ULID. Uses the Web Crypto API so the same
 *  implementation runs on the server, in the browser and on the edge. */
export function newId(): string {
  const bytes = new Uint8Array(RANDOM_LENGTH);
  globalThis.crypto.getRandomValues(bytes);
  let cursor = 0;
  return encodeTime(Date.now()) + encodeRandom(() => bytes[cursor++] ?? 0);
}

export function isUlid(value: string): boolean {
  return ULID_PATTERN.test(value);
}

/**
 * A deterministic id generator for tests and the seed script: same seed,
 * same sequence of ids. Uses a small xorshift PRNG and a fixed timestamp so
 * fixtures are byte-stable across runs.
 */
export function idFactory(seed: number): () => string {
  let state = (seed | 0) || 0x2545_f491;
  let counter = 0;

  const next = (): number => {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    return Math.abs(state);
  };

  return () => {
    counter += 1;
    // A fixed epoch keeps seeded ids stable; the counter keeps them ordered.
    return encodeTime(1_700_000_000_000 + counter) + encodeRandom(next);
  };
}
/**
 * Thin wrappers turning a Zod parse into an `AppErrorShape` without throwing.
 *
 * Server Actions parse `FormData` with `safeParse()` so a validation failure
 * comes back as a `Result` the form layer can render; pages parse
 * `searchParams` with `parseSearchParams()`, which never fails because a
 * hand-edited URL must not produce an error boundary.
 */
import type { Result } from "@/types/api";
import { err, ok } from "@/types/api";
import type { ZodType } from "zod";
import { fieldErrorsFromZod } from "./errors";

/** Parses without throwing; failures carry Zod's field errors verbatim. */
export function safeParse<TSchema extends ZodType>(
  schema: TSchema,
  raw: unknown,
): Result<unknown> {
  const parsed = schema.safeParse(raw);
  if (parsed.success) return ok<unknown>(parsed.data);

  return err<unknown>({
    code: "validation_failed",
    message: "Please correct the highlighted fields.",
    fieldErrors: fieldErrorsFromZod(parsed.error),
  });
}

/**
 * Normalises a Next `searchParams` record (values may be repeated, and are
 * always strings) and parses it. Because the pagination and sort schemas use
 * `.catch()` defaults, a malformed query string degrades to the defaults
 * rather than failing the render; a schema without catches will still throw,
 * which is the correct signal that the route needs one.
 */
export function parseSearchParams<TSchema extends ZodType>(
  schema: TSchema,
  raw: Readonly<Record<string, string | string[] | undefined>>,
): unknown {
  const normalized: Record<string, string | string[]> = {};
  for (const [key, value] of Object.entries(raw)) {
    if (value === undefined) continue;
    normalized[key] = value;
  }

  return schema.parse(normalized);
}
import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/** Registers a handler for one event type. Call the return value to detach. */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set = handlers.get(type) ?? new Set();
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };

