/**
 * Calendar-day arithmetic for recurring issues. Pure functions: safe to import
 * from both the client forms and the server.
 *
 * An occurrence is a `YYYY-MM-DD` day in the rule's own IANA time zone. Day D
 * has started at the instant that zone's wall clock reaches 00:00 on D, so
 * "has D started?" is the same question as "what calendar date does the zone
 * show right now?". Reading the date off the zone's clock keeps daylight-saving
 * transitions correct without any offset arithmetic.
 */
import type { RecurrenceCadence } from "@/types/recurring-issue";

const DAY_MS = 24 * 60 * 60 * 1000;

/** The part of a rule that decides which days are occurrences. */
export interface OccurrenceRule {
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly startsOn: string;
  readonly timezone: string;
}

const dateFormatters = new Map<string, Intl.DateTimeFormat>();

function dateFormatterFor(timeZone: string): Intl.DateTimeFormat {
  let formatter = dateFormatters.get(timeZone);
  if (formatter === undefined) {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    dateFormatters.set(timeZone, formatter);
  }
  return formatter;
}

/**
 * True when the runtime knows `value` as an IANA zone name. Numeric offsets
 * such as `+05:00` are rejected even where the runtime would parse them.
 */
export function isIanaTimeZone(value: string): boolean {
  if (value === "" || /^[+-]/.test(value)) return false;
  try {
    dateFormatterFor(value);
    return true;
  } catch {
    return false;
  }
}

/** The calendar date (`YYYY-MM-DD`) that `timeZone`'s wall clock shows at `instant`. */
export function localDateOn(instant: Date, timeZone: string): string {
  const parts = dateFormatterFor(timeZone).formatToParts(instant);
  const valueOf = (type: string): string =>
    parts.find((part) => part.type === type)?.value ?? "";
  return `${valueOf("year")}-${valueOf("month")}-${valueOf("day")}`;
}

/** ISO weekday of a `YYYY-MM-DD` day: 1 = Monday … 7 = Sunday. */
export function isoWeekdayOf(date: string): number {
  const weekday = new Date(`${date}T00:00:00Z`).getUTCDay();
  return weekday === 0 ? 7 : weekday;
}

/** Adds (or, with a negative count, subtracts) whole calendar days. */
export function addDays(date: string, days: number): string {
  const shifted = Date.parse(`${date}T00:00:00Z`) + days * DAY_MS;
  return new Date(shifted).toISOString().slice(0, 10);
}

/**
 * The latest occurrence day that has started by `now`, or `null` when none
 * has: the rule has not started yet, or a weekly rule's weekday has not fallen
 * on or after `startsOn`.
 */
export function latestOccurrenceOn(
  rule: OccurrenceRule,
  now: Date,
): string | null {
  const today = localDateOn(now, rule.timezone);
  if (today < rule.startsOn) return null;
  if (rule.cadence === "daily") return today;
  if (rule.weekday === null) return null;

  const daysSinceWeekday = (isoWeekdayOf(today) - rule.weekday + 7) % 7;
  const occurrence = addDays(today, -daysSinceWeekday);
  return occurrence >= rule.startsOn ? occurrence : null;
}

