/**
 * Files one ordinary issue per due recurring rule, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): createIssue, latestOccurrenceOn, isArchived
 */
import { PermissionDeniedError } from "@/lib/permissions";
import { createLogger } from "@/lib/logger";
import { latestOccurrenceOn } from "@/lib/recurrence";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import * as issueService from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/**
 * One pass per scheduler tick. A rule files at most one issue per run, for its
 * latest started occurrence, so a rule that was down for a week files one issue
 * when it returns rather than seven. A failing rule is logged and skipped; the
 * rest of the sweep carries on.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    for (const rule of await recurringIssueRepo.listActiveRecurringIssues()) {
      const occurrence = latestOccurrenceOn(rule, now);
      if (occurrence === null) continue;
      if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
        continue;
      }

      try {
        if (await fileOccurrence(rule, occurrence)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          occurrence,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Files the occurrence for one rule and returns whether an issue was created.
 * An archived project leaves the rule untouched, so it files once restored. A
 * creator who is gone, or whose role no longer allows issue creation, pauses
 * the rule. Any other refusal throws, leaving the rule as it was for a retry.
 */
async function fileOccurrence(
  rule: RecurringIssue,
  occurrence: string,
): Promise<boolean> {
  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) throw new Error(`Project ${rule.projectId} not found`);
  if (isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (creator === null || creator.status !== "active") {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return false;
  }

  const assignee =
    rule.assigneeId === null
      ? null
      : await memberRepo.findMember(rule.orgId, rule.assigneeId);

  try {
    await issueService.createIssue(
      { userId: rule.createdBy, orgId: rule.orgId, role: creator.role },
      {
        orgId: rule.orgId,
