import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { ZodError } from "zod";
import { newId } from "@/lib/id";
import { PermissionDeniedError } from "@/lib/permissions";
import { isIanaTimeZone, latestOccurrenceOn, localDateOn } from "@/lib/recurrence";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { drain, enqueue, resetQueue } from "@/server/jobs";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as recurringService from "@/server/services/recurring-issue-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("recur", "growth");
});

afterAll(() => {
  cleanup();
});

const validInput = () => ({
  orgId: tenant.org.id,
  projectId: tenant.project.id,
  title: "Daily triage",
  cadence: "daily" as const,
  timezone: "UTC",
  startsOn: "2026-03-01",
});

describe("occurrence days", () => {
  it("reads the calendar day off the zone's clock", () => {
    expect(localDateOn(new Date("2026-03-08T04:59:00Z"), "America/New_York")).toBe("2026-03-07");
    expect(localDateOn(new Date("2026-03-08T05:00:00Z"), "America/New_York")).toBe("2026-03-08");
  });

  it("daily: a day starts when the zone reaches midnight, across spring-forward", () => {
    const rule = { cadence: "daily" as const, weekday: null, startsOn: "2026-03-01", timezone: "America/New_York" };
    expect(latestOccurrenceOn(rule, new Date("2026-03-08T04:59:00Z"))).toBe("2026-03-07");
    expect(latestOccurrenceOn(rule, new Date("2026-03-08T05:00:00Z"))).toBe("2026-03-08");
    expect(latestOccurrenceOn({ ...rule, startsOn: "2026-03-09" }, new Date("2026-03-08T05:00:00Z"))).toBeNull();
  });

  it("weekly: latest matching ISO weekday on or after startsOn", () => {
    const friday = { cadence: "weekly" as const, weekday: 5, startsOn: "2026-02-01", timezone: "Asia/Tokyo" };
    expect(latestOccurrenceOn(friday, new Date("2026-03-05T14:59:00Z"))).toBe("2026-02-27");
    expect(latestOccurrenceOn(friday, new Date("2026-03-05T15:00:00Z"))).toBe("2026-03-06");
    const monday = { cadence: "weekly" as const, weekday: 1, startsOn: "2026-03-01", timezone: "UTC" };
    expect(latestOccurrenceOn(monday, new Date("2026-03-01T12:00:00Z"))).toBeNull();
    expect(latestOccurrenceOn(monday, new Date("2026-03-08T00:00:00Z"))).toBe("2026-03-02");
    const before = { cadence: "weekly" as const, weekday: 5, startsOn: "2026-02-27", timezone: "UTC" };
    expect(latestOccurrenceOn(before, new Date("2026-03-05T12:00:00Z"))).toBe("2026-02-27");
  });

  it("IANA zone names only", () => {
    expect(isIanaTimeZone("Asia/Tokyo")).toBe(true);
    expect(isIanaTimeZone("UTC")).toBe(true);
    expect(isIanaTimeZone("+05:00")).toBe(false);
    expect(isIanaTimeZone("Mars/Olympus")).toBe(false);
    expect(isIanaTimeZone("")).toBe(false);
  });
});

describe("createRecurringIssueSchema", () => {
  it("applies defaults", () => {
    const parsed = createRecurringIssueSchema.parse(validInput());
    expect(parsed).toMatchObject({ priority: "none", assigneeId: null, weekday: null });
  });

  it("enforces the cadence/weekday pairing", () => {
    expect(() => createRecurringIssueSchema.parse({ ...validInput(), cadence: "weekly" })).toThrow(ZodError);
    expect(() => createRecurringIssueSchema.parse({ ...validInput(), weekday: 3 })).toThrow(ZodError);
    expect(createRecurringIssueSchema.parse({ ...validInput(), cadence: "weekly", weekday: 7 }).weekday).toBe(7);
    expect(() => createRecurringIssueSchema.parse({ ...validInput(), cadence: "weekly", weekday: 8 })).toThrow(ZodError);
  });

  it("rejects unknown zones, impossible dates and short titles", () => {
    expect(() => createRecurringIssueSchema.parse({ ...validInput(), timezone: "Mars/Olympus" })).toThrow(ZodError);
    expect(() => createRecurringIssueSchema.parse({ ...validInput(), startsOn: "2026-02-30" })).toThrow(ZodError);
    expect(() => createRecurringIssueSchema.parse({ ...validInput(), startsOn: "2027-02-29" })).toThrow(ZodError);
    expect(createRecurringIssueSchema.parse({ ...validInput(), startsOn: "2028-02-29" }).startsOn).toBe("2028-02-29");
    expect(() => createRecurringIssueSchema.parse({ ...validInput(), title: "ab" })).toThrow(ZodError);
  });
});

describe("createRecurringIssue", () => {
  it("stores an unpaused, never-occurred rule created by the actor", async () => {
    const rule = await recurringService.createRecurringIssue(tenant.actors.owner, {
      ...validInput(),
      title: "Weekly planning",
      cadence: "weekly",
      weekday: 1,
      assigneeId: tenant.userIds.member,
    });
    expect(rule).toMatchObject({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      title: "Weekly planning",
      cadence: "weekly",
      weekday: 1,
      assigneeId: tenant.userIds.member,
      lastOccurrenceOn: null,
      paused: false,
      createdBy: tenant.userIds.owner,
    });
  });

  it("refuses viewers, foreign orgs, non-member assignees and archived projects", async () => {
    await expect(recurringService.createRecurringIssue(tenant.actors.viewer, validInput())).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(recurringService.createRecurringIssue(tenant.actors.owner, { ...validInput(), orgId: newId() as never })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(recurringService.createRecurringIssue(tenant.actors.owner, { ...validInput(), assigneeId: newId() as never })).rejects.toThrow();

    const archived = await projectRepo.insertProject({
      orgId: tenant.org.id, name: "Archived", slug: "archived", key: "ARCH", description: null,
      visibility: "org", leadId: null, color: "#6366f1", targetDate: null,
    });
    await projectRepo.archiveProject(tenant.org.id, archived.id);
    await expect(recurringService.createRecurringIssue(tenant.actors.owner, { ...validInput(), projectId: archived.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("enforces the plan cap, paused rules included, and stores nothing past it", async () => {
    const free = await createTenant("recur-free", "free");
    await expect(recurringService.createRecurringIssue(free.actors.owner, { ...validInput(), orgId: free.org.id, projectId: free.project.id })).rejects.toThrow();
    expect(await recurringRepo.countRecurringIssues(free.org.id)).toBe(0);

    const starter = await createTenant("recur-starter", "starter");
    const input = { ...validInput(), orgId: starter.org.id, projectId: starter.project.id };
    const first = await recurringService.createRecurringIssue(starter.actors.owner, { ...input, title: "Rule one" });
    await recurringService.createRecurringIssue(starter.actors.owner, { ...input, title: "Rule two" });
    await recurringService.createRecurringIssue(starter.actors.owner, { ...input, title: "Rule three" });
    await recurringService.setRecurringIssuePaused(starter.actors.owner, { orgId: starter.org.id, recurringIssueId: first.id, paused: true });
    await expect(recurringService.createRecurringIssue(starter.actors.owner, { ...input, title: "Rule four" })).rejects.toThrow();
    expect(await recurringRepo.countRecurringIssues(starter.org.id)).toBe(3);
  });

  it("lists in creation order; viewers may read, foreign orgs may not", async () => {
    const starter = await createTenant("recur-order", "starter");
    const input = { ...validInput(), orgId: starter.org.id, projectId: starter.project.id };
    for (const title of ["Alpha", "Bravo", "Charlie"]) {
      await recurringService.createRecurringIssue(starter.actors.owner, { ...input, title });
    }
    const listed = await recurringService.listRecurringIssues(starter.actors.viewer, starter.org.id);
    expect(listed.map((rule) => rule.title)).toEqual(["Alpha", "Bravo", "Charlie"]);
    await expect(recurringService.listRecurringIssues(starter.actors.owner, tenant.org.id)).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("pauses and resumes with issue:create; unknown ids are not found", async () => {
    const rule = await recurringService.createRecurringIssue(tenant.actors.owner, { ...validInput(), title: "Pausable" });
    await expect(recurringService.setRecurringIssuePaused(tenant.actors.viewer, { orgId: tenant.org.id, recurringIssueId: rule.id, paused: true })).rejects.toBeInstanceOf(PermissionDeniedError);
    const paused = await recurringService.setRecurringIssuePaused(tenant.actors.owner, { orgId: tenant.org.id, recurringIssueId: rule.id, paused: true });
    expect(paused.paused).toBe(true);
    const resumed = await recurringService.setRecurringIssuePaused(tenant.actors.owner, { orgId: tenant.org.id, recurringIssueId: rule.id, paused: false });
    expect(resumed.paused).toBe(false);
    await expect(recurringService.setRecurringIssuePaused(tenant.actors.owner, { orgId: tenant.org.id, recurringIssueId: newId(), paused: true })).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("runRecurringIssueJob", () => {
  const titled = async (prefix: string) =>
    (await issueRepo.listIssues({ orgId: tenant.org.id, projectId: tenant.project.id, limit: 100, cursor: null })).items
      .map((issue) => issue.title)
      .filter((title) => title.startsWith(prefix));

  it("files one issue for the latest occurrence, once", async () => {
    const rule = await recurringService.createRecurringIssue(tenant.actors.owner, {
      ...validInput(), title: "Daily triage", priority: "high", assigneeId: tenant.userIds.member,
    });
    const now = new Date("2026-03-05T07:00:00Z");

    const result = await runRecurringIssueJob(now);
    expect(result.kind).toBe("recurring-issues");

    const page = await issueRepo.listIssues({ orgId: tenant.org.id, projectId: tenant.project.id, limit: 100, cursor: null });
    const filed = page.items.filter((issue) => issue.title === "Daily triage (2026-03-05)");
    expect(filed).toHaveLength(1);
    expect(filed[0]).toMatchObject({ status: "backlog", priority: "high", assigneeId: tenant.userIds.member, description: null, dueAt: null, authorId: tenant.userIds.owner, labelIds: [] });

    expect((await recurringRepo.findRecurringIssueById(tenant.org.id, rule.id))?.lastOccurrenceOn).toBe("2026-03-05");
    await runRecurringIssueJob(now);
    expect((await titled("Daily triage (2026-03-05)")).length).toBe(1);
  });

  it("never back-fills missed occurrences", async () => {
    const rule = await recurringService.createRecurringIssue(tenant.actors.owner, { ...validInput(), title: "Backlog check" });
    await runRecurringIssueJob(new Date("2026-03-09T07:00:00Z"));
    expect((await titled("Backlog check (")).sort()).toEqual(["Backlog check (2026-03-09)"]);
    expect((await recurringRepo.findRecurringIssueById(tenant.org.id, rule.id))?.lastOccurrenceOn).toBe("2026-03-09");
  });

  it("files unassigned when the assignee has left the org", async () => {
    const user = await userRepo.insertUser({ email: "leaver@recur.test", name: "Leaver", passwordHash: "seed" });
    const member = await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
    await recurringService.createRecurringIssue(tenant.actors.owner, { ...validInput(), title: "Leaver rule", assigneeId: user.id });
    await memberRepo.archiveMember(tenant.org.id, member.id);
    await runRecurringIssueJob(new Date("2026-03-10T07:00:00Z"));
    const page = await issueRepo.listIssues({ orgId: tenant.org.id, projectId: tenant.project.id, limit: 100, cursor: null });
    const filed = page.items.find((issue) => issue.title === "Leaver rule (2026-03-10)");
    expect(filed?.assigneeId).toBeNull();
  });

  it("pauses and files nothing when the creator's role no longer allows it", async () => {
    const user = await userRepo.insertUser({ email: "demoted@recur.test", name: "Demoted", passwordHash: "seed" });
    const member = await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
    const actor = { userId: user.id, orgId: tenant.org.id, role: "member" as const };
    const rule = await recurringService.createRecurringIssue(actor, { ...validInput(), title: "Demoted rule" });
    await memberRepo.updateMemberRole(tenant.org.id, member.id, "viewer");
    await runRecurringIssueJob(new Date("2026-03-12T07:00:00Z"));
    expect((await titled("Demoted rule")).length).toBe(0);
    expect((await recurringRepo.findRecurringIssueById(tenant.org.id, rule.id))?.paused).toBe(true);
  });

  it("pauses when the creator has been removed", async () => {
    const user = await userRepo.insertUser({ email: "removed@recur.test", name: "Removed", passwordHash: "seed" });
    const member = await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
    const actor = { userId: user.id, orgId: tenant.org.id, role: "member" as const };
    const rule = await recurringService.createRecurringIssue(actor, { ...validInput(), title: "Removed rule" });
    await memberRepo.archiveMember(tenant.org.id, member.id);
    await runRecurringIssueJob(new Date("2026-03-12T07:00:00Z"));
    expect((await titled("Removed rule")).length).toBe(0);
    expect((await recurringRepo.findRecurringIssueById(tenant.org.id, rule.id))?.paused).toBe(true);
  });

  it("skips an archived project untouched, then files the latest occurrence once restored", async () => {
    const project = await projectRepo.insertProject({
      orgId: tenant.org.id, name: "Ops", slug: "ops", key: "OPS", description: null,
      visibility: "org", leadId: null, color: "#6366f1", targetDate: null,
    });
    const rule = await recurringService.createRecurringIssue(tenant.actors.owner, {
      ...validInput(), projectId: project.id, title: "Ops check",
    });
    await projectRepo.archiveProject(tenant.org.id, project.id);
    await runRecurringIssueJob(new Date("2026-03-15T07:00:00Z"));
    expect((await recurringRepo.findRecurringIssueById(tenant.org.id, rule.id))).toMatchObject({ lastOccurrenceOn: null, paused: false });

    await projectRepo.restoreProject(tenant.org.id, project.id);
    await runRecurringIssueJob(new Date("2026-03-15T07:00:00Z"));
    const page = await issueRepo.listIssues({ orgId: tenant.org.id, projectId: project.id, limit: 100, cursor: null });
    expect(page.items.map((issue) => issue.title)).toEqual(["Ops check (2026-03-15)"]);
    expect((await recurringRepo.findRecurringIssueById(tenant.org.id, rule.id))?.lastOccurrenceOn).toBe("2026-03-15");
  });

  it("runs from the job queue under the recurring-issues kind", async () => {
    resetQueue();
    enqueue({ id: "recurring-issues:scratch", kind: "recurring-issues", runAt: toIsoTimestamp(new Date()), attempts: 0, payload: {} });
    await expect(drain()).resolves.toBe(1);
    resetQueue();
  });
});

